import java.util.*;

class Solution {
    public boolean isBalanced(TreeNode root) {
        return check(root) != -1;
    }

    // returns the height, or -1 if this subtree is unbalanced
    private int check(TreeNode n) {
        if (n == null) return 0;
        int a = check(n.left);
        if (a == -1) return -1;
        int b = check(n.right);
        if (b == -1 || Math.abs(a - b) > 1) return -1;
        return 1 + Math.max(a, b);
    }
}

